import bisect
import hashlib


def _hash(s):
    return int(hashlib.md5(s.encode('utf-8')).hexdigest(), 16)


class HashRing:
    def __init__(self, nodes, replicas=100):
        self.replicas = replicas
        self._ring = {}
        self._sorted_points = []
        for node in nodes:
            self.add_node(node)

    def add_node(self, node):
        for i in range(self.replicas):
            point = _hash(f'{node}:{i}')
            self._ring[point] = node
        self._sorted_points = sorted(self._ring)

    def remove_node(self, node):
        for i in range(self.replicas):
            point = _hash(f'{node}:{i}')
            self._ring.pop(point, None)
        self._sorted_points = sorted(self._ring)

    def get_node(self, key):
        if not self._ring:
            raise ValueError('no nodes')
        point = _hash(key)
        idx = bisect.bisect(self._sorted_points, point)
        if idx == len(self._sorted_points):
            idx = 0
        return self._ring[self._sorted_points[idx]]

    @property
    def nodes(self):
        return sorted(set(self._ring.values()))

